def _cell(value):
    """CSV cell; text that a spreadsheet could run as a formula is prefixed with a quote."""
    if value is None:
        return ""
    if not isinstance(value, str):
        return str(value)
    if value[:1] in ("\t", "\r"):
        return "'" + value
    if value[:1] in ("=", "+", "-", "@"):
        try:
            float(value)
        except ValueError:
            return "'" + value
    return value


class EntityViewSet(viewsets.ModelViewSet):
    entity = None
    permission_classes = [EntityPermission]
    http_method_names = ["get", "post", "patch", "delete", "head", "options"]

    def get_queryset(self):
        model = apps.get_model("entities", ENTITIES[self.entity]["model"])
        qs = model.objects.all().order_by("-pk")
        if self.action in ("partial_update", "destroy"):
            # Called inside transaction.atomic: lock the row so the permission check
            # and the write see the committed state.
            qs = qs.select_for_update()
        return qs

    def partial_update(self, request, *args, **kwargs):
        with transaction.atomic():
            return super().partial_update(request, *args, **kwargs)

    def destroy(self, request, *args, **kwargs):
        with transaction.atomic():
            return super().destroy(request, *args, **kwargs)

    def get_serializer_class(self):
        return build_serializer(self.entity)

    def perform_create(self, serializer):
        serializer.save(created_by=self.request.user)

    @action(detail=False, methods=["get"])
    def export(self, request):
        """CSV of the readable scalar fields of every record."""
        spec = ENTITIES[self.entity]
        columns = ["id"]
        if spec["numbering"]:
            columns.append("number")
        if self.entity in WORKFLOWS:
            columns.append("state")
        columns += spec["attrs"] + ["created_by", "created_at", "modified_at"]
        response = HttpResponse(content_type="text/csv")
        response["Content-Disposition"] = f'attachment; filename="{self.entity}.csv"'
        writer = csv.writer(response)
        writer.writerow(columns)
        for obj in self.get_queryset().select_related("created_by"):
            row = []
            for col in columns:
                value = getattr(obj, col)
                if col == "created_by":
                    value = value.get_username() if value else ""
                elif obj._meta.get_field(col).is_relation:
                    value = getattr(obj, col + "_id")
                elif hasattr(value, "name") and hasattr(value, "storage"):
                    value = value.name
                row.append(_cell(value))
            writer.writerow(row)
        return response

    @action(detail=True, methods=["post"])
    def transition(self, request, pk=None):
        obj = self.get_object()
        body = request.data
        if not isinstance(body, Mapping):
            return Response({"detail": "Expected a JSON object."}, status=400)
        body = {k: v for k, v in body.items()}
        name = body.pop("action", None)
        if not isinstance(name, str) or not name:
            return Response({"detail": "'action' is required."}, status=400)
        try:
            obj = apply_transition(obj, name, request.user, body)
        except TransitionDenied as exc:
            payload = {"detail": exc.reason}
            if exc.fields:
                payload["fields"] = exc.fields
            return Response(payload, status=exc.status)
        return Response(self.get_serializer(obj).data)


def viewset_for(entity):
    return type(
        f"{ENTITIES[entity]['model']}ViewSet", (EntityViewSet,), {"entity": entity}
    )


class ReportView(APIView):
    """GET /api/reports/<name>/ for roles that list the report."""

    permission_classes = [IsAuthenticated]

    def get(self, request, name):
        if name not in REPORTS:
            return Response({"detail": "Unknown report."}, status=404)
        if not any(name in REPORT_ACCESS.get(r, []) for r in user_roles(request.user)):
            return Response(
                {"detail": "You do not have permission to run this report."}, status=403
            )
        rows = reports.run_report(name, request.query_params.dict())
        return Response(
            {"name": name, "columns": reports.REPORT_SPECS[name]["columns"], "rows": rows}
        )
